import { z } from "zod";
export const CheckRun = z.object({
  name: z.string(),  // "vitest related", "e2e/pr/projects-table-empty-state.spec.ts"
  command: z.string(),
  result: z.enum(["pass", "fail", "fails_on_main_too", "not_run"]),
  why: z.string(),  // one line for the reviewer
  proof: z.string().nullish(),  // S3 key of the output, video or trace
  qa_check: z.string().nullish(),  // "QA-2" when it proves a QA plan check
});
export const ChecksRecord = z.object({
  kind: z.string(),  // from readiness: fe_bug, be_bug, ...
  services_started: z.array(z.string()),  // [] for a lint-only change
  ran: z.array(CheckRun),
  skipped: z.array(z.tuple([z.string(), z.string()])),  // [check, reason]
});

/** A starting point from the checking guide. Nova decides; this never blocks or forces a check. */
export function suggestStart(changed: string[]): { checks: string[]; services: string[] } {
  const fe = changed.filter((p) => p.startsWith("frontend/src/"));
  const be = changed.filter((p) => p.startsWith("cloud/") || p.startsWith("client/"));
  const checks: string[] = [];
  const services: string[] = [];
  if (fe.length) {
    checks.push("npm run lint", "npm run check-types", "npx vitest --run --changed origin/main");
    if (fe.some((p) => p.startsWith("frontend/src/app/"))) {
      checks.push("the Playwright spec for this flow (frontend/e2e/pr/)");
      services.push("postgres-service", "web-service", "redis");  // cloud/rhinoCloud/docker-compose.yml names
    }
  }
  if (be.length) checks.push("pre-commit run --files <changed>", "./scripts/local_run_backend_unit_tests.sh cloud <module path>");
  return { checks, services };
}

import { readFile } from "node:fs/promises";
import { query } from "@anthropic-ai/claude-agent-sdk/core";
import { z } from "zod";
const PROBLEMS = ["not_observable", "no_edge_case", "missing_screen_state", "reads_implementation", "wrong_proof",
  "not_the_ticket"] as const;
export const Cosign = z.object({
  sign: z.boolean(),
  changes: z.array(z.object({
    check: z.string(),  // "QA-2", or "new" for a missing check
    problem: z.enum(PROBLEMS),
    suggestion: z.string(),
  })),
});
export type Cosign = z.infer<typeof Cosign>;
export async function cosign(ticketText: string, qaPlanJson: string): Promise<Cosign> {
  const prompt = `Ticket:\n${ticketText}\n\nProposed QA plan:\n${qaPlanJson}\n\nWould these checks fail on a broken build?`;
  for await (const msg of query({ prompt, options: {
    model: "claude-sonnet-5-5", effort: "medium", tools: [], settingSources: [],  // its own session, not a Nova subagent
    systemPrompt: await readFile(new URL("../prompts/qa-cosign.md", import.meta.url), "utf8"),  // goals + 4 weak-plan examples
    outputFormat: { type: "json_schema", schema: z.toJSONSchema(Cosign) },
  } })) {
    if (msg.type === "result" && msg.subtype === "success") return Cosign.parse(msg.structured_output);
  }
  throw new Error("the QA agent returned no co-sign result");
}

import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { relative, resolve } from "node:path";
import type { HookCallback } from "@anthropic-ai/claude-agent-sdk/core";

const REPO = "/work/fcp";
const LOCK = "/work/.nova/locked.json";  // outside the checkout; path per G3's harness layout

const digest = (rel: string) => createHash("sha256").update(readFileSync(resolve(REPO, rel))).digest("hex");
const locked = (): Record<string, string> => (existsSync(LOCK) ? JSON.parse(readFileSync(LOCK, "utf8")) : {});

/** Called by the harness once every QA test was shown failing on the unchanged code. */
export function lock(testFiles: string[]): void {
  writeFileSync(LOCK, JSON.stringify(Object.fromEntries(testFiles.map((rel) => [rel, digest(rel)]))));
}

export const denyLockedEdits: HookCallback = async (input) => {  // PreToolUse, matcher "Edit|Write"
  if (input.hook_event_name !== "PreToolUse") return {};
  const path = (input.tool_input as { file_path?: string }).file_path;
  if (!path || !Object.hasOwn(locked(), relative(REPO, resolve(path)))) return {};
  return { hookSpecificOutput: {
    hookEventName: "PreToolUse",
    permissionDecision: "deny",
    permissionDecisionReason: "This test is a locked QA check for this ticket. Add a new test instead, " +
      "or ask the requester to change the QA plan.",
  } };
};

/** For the Stop hook: catches edits made through Bash too. */
export function changedLockedFiles(): string[] {
  const changed = (rel: string, d: string) => !existsSync(resolve(REPO, rel)) || digest(rel) !== d;
  return Object.entries(locked()).filter(([rel, d]) => changed(rel, d)).map(([rel]) => rel);
}
